changeSet.sql:
UPDATE characters SET equipslots = LEAST(equipslots * 2, 96), useslots = LEAST(useslots * 2, 96),
                      setupslots = LEAST(setupslots * 2, 96), etcslots = LEAST(etcslots * 2, 96);
ALTER TABLE characters ALTER equipslots SET DEFAULT 48, ALTER useslots SET DEFAULT 48,
                       ALTER setupslots SET DEFAULT 48, ALTER etcslots SET DEFAULT 48;
